    "content": "'use client';

import Link from 'next/link';
import { motion } from 'framer-motion';

interface OriginalHeroProps {
    city?: string;
    theme?: {
        overlay?: string;
        primary?: string;
    };
}

export function OriginalHero({ city, theme }: OriginalHeroProps) {
    const title = city 
        ? `Immobiliengutachter in ${city}`
        : 'Deutschlandweite Immobilien- und Grundstücksbewertungen von fachkundigen Gutachtern';

    const subtitle = city
        ? `Verkehrswertgutachten und Wertindikationen von Ihrem regionalen Experten in ${city}`
        : 'Verkehrswertgutachten und Wertindikationen von regionalen Experten';

    return (
        <section
            style={{
                position: 'relative',
                minHeight: '80vh',
                display: 'flex',
                alignItems: 'center',
                paddingTop: '80px',
                color: 'white',
                overflow: 'hidden'
            }}
        >
            {/* HTML5 Video Background */}
            <video
                autoPlay
                loop
                muted
                playsInline
                style={{
                    position: 'absolute',
                    top: '50%',
                    left: '50%',
                    minWidth: '100%',
                    minHeight: '100%',
                    width: 'auto',
                    height: 'auto',
                    transform: 'translate(-50%, -50%)',
                    objectFit: 'cover',
                    zIndex: 0
