                        transition={{ duration: 0.8, delay: 0.6 }}
                        style={{ display: 'flex', gap: '1.5rem', flexWrap: 'wrap' }}
                    >
                        <Link href="/kontakt" className="btn hover-lift" style={{
                            backgroundColor: '#c5a36c', /* Lasarz Gold */
